from genesis.engine.solvers.rigid.stress.pipeline import *
from genesis.engine.solvers.rigid.stress.recovery import *
from genesis.engine.solvers.rigid.stress.balance import *
workspaces = {}

@qd.func
def func_balance_fallback(omega: qd.Tensor, stress_state: StressState, stress_info: StressInfo, enabled: bool):
    for i_b in range(qd.select(enabled, stress_state.active.shape[0], 0)):
        stress_state.wrench[i_b] = qd.Vector.zero(gs.qd_float, 6)
    qd.loop_config(block_dim=256)
    for i_thread in range(qd.select(enabled, (stress_info.vertices.shape[0] + 7) // 8 * ((stress_state.active.shape[0] + 31) // 32) * 256, 0)):
        i_t = qd.simt.block.thread_idx()
        i_blk = i_thread // 256
        n_env_tiles = (stress_state.active.shape[0] + 31) // 32
        (i_row, i_col) = (i_t // 32, i_t % 32)
        i_n = i_blk // n_env_tiles * 8 + i_row
        i_b = i_blk % n_env_tiles * 32 + i_col
        sh_wrench = qd.simt.block.SharedArray((6, 8, 32), gs.qd_float)
        wrench = qd.Vector.zero(gs.qd_float, 6)
        if i_n < stress_info.vertices.shape[0] and i_b < stress_state.active.shape[0]:
            w = omega[i_b]
            terms = qd.Vector([w[0] * w[0], w[1] * w[1], w[2] * w[2], w[0] * w[1], w[0] * w[2], w[1] * w[2]])
            load = stress_state.force[i_n, i_b] + stress_info.centrifugal[i_n] @ terms
            stress_state.rhs[i_n, i_b] = load
            wrench = stress_info.modes[i_n].transpose() @ load
        for a in qd.static(range(6)):
            sh_wrench[a, i_row, i_col] = wrench[a]
        qd.simt.block.sync()
        if i_row == 0 and i_b < stress_state.active.shape[0]:
            total = qd.Vector.zero(gs.qd_float, 6)
            for j_row in qd.static(range(8)):
                for a in qd.static(range(6)):
                    total[a] += sh_wrench[a, j_row, i_col]
            for a in qd.static(range(6)):
                qd.atomic_add(stress_state.wrench[i_b][a], total[a])
        qd.simt.block.sync()
    for (i_n, i_b) in qd.ndrange(stress_info.vertices.shape[0], qd.select(enabled, stress_state.active.shape[0], 0)):
        stress_state.rhs[i_n, i_b] -= stress_info.relief[i_n] @ stress_state.wrench[i_b]

@qd.kernel
def kernel_centrifugal_wrench(info: StressInfo, centrifugal_wrench: qd.Tensor):
    for i in range(1):
        centrifugal_wrench[None] = qd.Matrix.zero(gs.qd_float, 6, 6)
    for i_n in range(info.vertices.shape[0]):
        value = info.modes[i_n].transpose() @ info.centrifugal[i_n]
        for a, b in qd.static(qd.ndrange(6, 6)):
            qd.atomic_add(centrifugal_wrench[None][a, b], value[a, b])

@qd.func
def func_balance_reuse(
    omega: qd.Tensor, state: StressState, info: StressInfo,
    contacts: StressContactState, scatter: StressScatterWorkspace,
    centrifugal_wrench: qd.Tensor,
):
    admitted = scatter.count[None] <= scatter.tasks.shape[0]
    for i_b in range(qd.select(admitted, state.active.shape[0], 0)):
        w = omega[i_b]
        terms = qd.Vector([w[0]*w[0], w[1]*w[1], w[2]*w[2], w[0]*w[1], w[0]*w[2], w[1]*w[2]])
        state.wrench[i_b] = centrifugal_wrench[None] @ terms
    for i_pair in range(qd.select(admitted, contacts.active_count[None], 0)):
        pair = contacts.active_pairs[i_pair]
        i_c, i_b = pair[0], pair[1]
        if contacts.status[i_c, i_b] == 0:
            accumulated = scatter.wrench[i_pair]
            force = qd.Vector([accumulated[a] for a in qd.static(range(3))])
            moment = qd.Vector([accumulated[a+3] for a in qd.static(range(3))])
            com = qd.Vector([info.mass_properties[a + 1] for a in qd.static(range(3))]) / info.mass_properties[0]
            moment += (contacts.position[i_c, i_b] - com).cross(force)
            for a in qd.static(range(3)):
                qd.atomic_add(state.wrench[i_b][a], force[a])
                qd.atomic_add(state.wrench[i_b][a+3], moment[a])
    for i_n, i_b in qd.ndrange(info.vertices.shape[0], qd.select(admitted, state.active.shape[0], 0)):
        w = omega[i_b]
        terms = qd.Vector([w[0]*w[0], w[1]*w[1], w[2]*w[2], w[0]*w[1], w[0]*w[2], w[1]*w[2]])
        state.rhs[i_n, i_b] = state.force[i_n, i_b] + info.centrifugal[i_n] @ terms - info.relief[i_n] @ state.wrench[i_b]
    func_balance_fallback(omega, state, info, not admitted)

@qd.kernel(graph=True)
def kernel_balance_reuse(
    omega: qd.Tensor, state: StressState, info: StressInfo,
    contacts: StressContactState, scatter: StressScatterWorkspace,
    centrifugal_wrench: qd.Tensor,
):
    func_balance_reuse(omega, state, info, contacts, scatter, centrifugal_wrench)
@qd.kernel(graph=True)
def kernel_reuse_pipeline(young: float, poisson: float, tolerance: float, absolute: float, epsilon: float, link: int, offsets_pos: qd.types.ndarray(), offsets_quat: qd.types.ndarray(), omega: qd.Tensor, dyn: array_class.DynState, collider: array_class.ColliderState, state: StressState, contacts: StressContactState, info: StressInfo, surface: StressSurfaceInfo, boundary: StressSurfaceInverseInfo, inverse: StressInverseInfo, factor: StressFactorInfo, scatter: StressScatterWorkspace, errno: qd.Tensor, batch_offsets: qd.template(), first: qd.template(), enable: bool, corrections: qd.template(), cached_peak: qd.template(), cached_bounds: qd.template(), n_nodes: qd.template(), full: qd.template(), face_parallel: qd.template(), is_cooperative_balance: qd.template(), centrifugal_wrench: qd.Tensor):
