        func_balance(omega, state, info, is_cooperative_balance)
    func_direct_init(state)
    func_surface_pack(state, boundary)
    func_surface_apply_packed(young, omega, state, boundary)
    func_full_residual(young, tolerance, absolute, state, info, False)
    for _ in qd.static(range(corrections)):
        func_apply_inverse(young, state, inverse, True, False)
        func_full_residual(young, tolerance, absolute, state, info, True)
    func_solve_cooperative(young, state, info, factor, n_nodes, True)
    func_full_residual(young, tolerance, absolute, state, info, True)
    func_peak_impl(young, poisson, state, info, cached_peak, full)
    func_accept(state, contacts, errno, full)

def recover(self, i_substep: int) -> None:
    solver = self.solver
    for entry in self.links:
        options = entry.link.stress_options
        if options.output_mode != entry.output_mode:
            gs.raise_exception('Changing stress output mode requires rebuilding the scene.')
        if gs.backend == gs.cuda and options.fused_pipeline and (entry.model.surface_inverse is not None) and options.packed_surface_loads and options.cooperative_pressure and options.cooperative_scatter and options.cooperative_solve and (entry.model.info.vertices.shape[0] <= 1024) and (entry.history is None):
            kernel_reuse_pipeline(options.young, options.poisson, options.tolerance, options.absolute_tolerance, self.source_epsilon, entry.link.idx, solver._links_offset_pos, solver._links_offset_quat, entry.omega, solver.dyn_state, solver.collider.collider_state, entry.state, entry.contacts, entry.model.info, entry.surface.info, entry.model.surface_inverse.info, entry.model.inverse.info, entry.model.factor.info, entry.scatter, solver._errno, solver._links_offset_quat.ndim == 3, i_substep == 0, not solver._disable_constraint, options.inverse_corrections, options.cached_peak, options.cached_face_bounds, entry.model.info.vertices.shape[0], entry.output_mode == 'full', entry.scatter.tasks.shape[0] > 0, options.cooperative_balance, workspaces[id(entry.state)])
            continue
