            kernel_begin_step(entry.state)
        kernel_associate(entry.link.idx, solver._links_offset_pos, solver._links_offset_quat, entry.omega, solver.dyn_state, entry.contacts, solver.collider.collider_state, solver._links_offset_quat.ndim == 3, not solver._disable_constraint, entry.state.step_valid, solver._errno)
        kernel_anchor(self.source_epsilon, entry.contacts, entry.surface.info)
        kernel_pressure(entry.contacts, entry.surface.info, entry.link.stress_options.cooperative_pressure)
        if entry.scatter.tasks.shape[0] and options.cooperative_scatter:
            kernel_scatter_faces(entry.contacts, entry.state, entry.model.info, entry.surface.info, entry.scatter, options.cached_face_bounds)
        else:
            kernel_scatter(entry.contacts, entry.state, entry.model.info, entry.surface.info, options.cooperative_scatter, options.cached_face_bounds)
        entry.model.recover(entry.omega, entry.state, entry.link.stress_options, entry.history, surface_load=True)
        kernel_accept(entry.state, entry.contacts, solver._errno)
        if entry.history is not None:
            entry.history.append(entry.state)
